// Shared by the two embedded Tasker JavaScriptlets. No root required.
function totoSnapshot(allowMissing) {
    var command = "d=/storage/emulated/0/Pictures/Toto; " +
        "if [ ! -e \"$d\" ]; then " + (allowMissing ? "echo TOTO_OK; exit 0; " : "exit 1; ") + "fi; " +
        "[ -d \"$d\" ] && [ -r \"$d\" ] && [ -x \"$d\" ] || exit 1; " +
        "for f in \"$d\"/*; do [ -f \"$f\" ] || continue; " +
        "case \"$f\" in *.[pP][nN][gG]|*.[jJ][pP][gG]|*.[jJ][pP][eE][gG]|*.[wW][eE][bB][pP]) " +
        "stat -c '%s|%y|%n' \"$f\" || exit 1;; esac; done; echo TOTO_OK";
    var output = shell(command, false, 20);
    if (typeof output !== "string" || !/TOTO_OK\s*$/.test(output)) {
        throw new Error("Cannot read Pictures/Toto. Check Tasker file access.");
    }
    var files = {};
    output.replace(/TOTO_OK\s*$/, "").split("\n").forEach(function (line) {
        if (!line) return;
        var match = /^(\d+)\|([^|]+)\|(\/storage\/emulated\/0\/Pictures\/Toto\/[^\r\n]+)$/.exec(line);
        if (!match) throw new Error("Unsupported image filename or file metadata.");
        files[match[3]] = {size: Number(match[1]), stamp: match[1] + "|" + match[2]};
    });
    return files;
}

function totoSelect(before, after, stable) {
    var changed = Object.keys(after).filter(function (path) {
        return !before[path] || before[path].stamp !== after[path].stamp;
    });
    if (changed.length !== 1) {
        throw new Error(changed.length ? "Several images changed; cannot choose the result safely." :
            "No new or updated result image. Nothing sent.");
    }
    var path = changed[0];
    var finalChanged = Object.keys(stable).filter(function (name) {
        return !before[name] || before[name].stamp !== stable[name].stamp;
    });
    if (finalChanged.length !== 1 || finalChanged[0] !== path) {
        throw new Error("Image selection changed while checking. Nothing sent.");
    }
    if (!after[path].size || !stable[path] || stable[path].stamp !== after[path].stamp) {
        throw new Error("Result image is empty or still being written. Nothing sent.");
    }
    return path;
}

var toto_before = "";
var toto_ready = "false";
var toto_error = "";
try {
    toto_before = JSON.stringify(totoSnapshot(true));
    toto_ready = "true";
} catch (error) {
    toto_error = String(error.message || error);
    flashLong("Toto: " + toto_error);
}

