var toto_share_ready = "false";
var toto_image = "";
var toto_uri = "";
var toto_error = "";
try {
    if (String(typeof result === "undefined" ? "" : result) !== "0") {
        throw new Error("Termux did not report success. Nothing sent.");
    }
    var toto_first = totoSnapshot(false);
    shell("sleep 1", false, 3);
    toto_image = totoSelect(JSON.parse(toto_before), toto_first, totoSnapshot(false));
    toto_uri = "file://" + toto_image.split("/").map(encodeURIComponent).join("/");
    // Only indicates a validated file. The next native Send Intent action
    // launches WhatsApp and stops the task if Android reports a launch error.
    toto_share_ready = "true";
} catch (error) {
    toto_error = String(error.message || error);
    flashLong("Toto: " + toto_error);
}

import android.app.Activity;
import android.content.Intent;
import android.content.ClipData;
import android.net.Uri;
import java.util.function.Consumer;
import java.util.concurrent.TimeUnit;
import io.reactivex.subjects.SingleSubject;

/* FilePathToContentUri supplies this using Tasker's configured provider. */
String value = tasker.getVariable("content_uri");
if (value == null || !value.startsWith("content://")) {
    throw new IllegalStateException("Tasker did not create a content URI for the image.");
}
final Uri imageUri = Uri.parse(value);
tasker.setVariable("toto_uri", value);
final Intent shareIntent = new Intent(Intent.ACTION_SEND);
shareIntent.setType("image/*");
shareIntent.setPackage("com.whatsapp");
shareIntent.putExtra(Intent.EXTRA_STREAM, imageUri);
shareIntent.putExtra("jid", "6281286373886@s.whatsapp.net");
shareIntent.setClipData(ClipData.newRawUri("Toto result", imageUri));
shareIntent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);

/* Launch from an Activity, and wait for the callback before AutoInput starts. */
final SingleSubject launched = SingleSubject.create();
tasker.doWithActivity(new Consumer() {
    accept(Object value) {
        Activity activity = (Activity) value;
        try {
            activity.startActivity(shareIntent);
            launched.onSuccess("WhatsApp share activity requested");
        } catch (Exception error) {
            launched.onError(error);
        } finally {
            activity.finish();
        }
    }
});
return launched.timeout(15, TimeUnit.SECONDS).blockingGet();
